INSERT INTO verses (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at) VALUES
(53711, 'Exodus 18:25', 'Exodus', 18, 25, 'او د ټولو اسراییلیانو څخه یې لایقه کسان وټاکل. هغوی یې په زر کسیزه، سل کسیزه، پنځوس کسیزه او لس کسیزه ډلو باندې مشران وټاکل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus18_verse_25.mp3', '', 1761754199, 1761754199),
(53712, 'Exodus 18:26', 'Exodus', 18, 26, 'هغوی به تل د قاضیانو په توګه د خلکو خدمت کاوه. هغوی به سختې دعوې موسی ته راوړلې، خو د ساده دعوو پرېکړه به یې په خپله کوله.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus18_verse_26.mp3', '', 1761754199, 1761754199),
(53713, 'Exodus 18:27', 'Exodus', 18, 27, 'بیا موسی خپل خسر یترون رخصت کړ او یترون خپل وطن ته ستون شو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus18_verse_27.mp3', '', 1761754199, 1761754199),
(53714, 'Psalms 26:1', 'Psalms', 26, 1, 'ته ښکاره کړه ای څښتنه چې زه یمه بې‌ګناه دې دپاره چې کومه سم کارونه او په تا باندې توکل کومه بې له شکه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms26_verse_1.mp3', '', 1761754199, 1761754199),
(53715, 'Psalms 26:2', 'Psalms', 26, 2, 'کړه امتحان مې ای څښتنه او مې وازمایلو زما د زړه او ذهن دواړو ازمېښت وکړه ته', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms26_verse_2.mp3', '', 1761754199, 1761754199),
(53716, 'Psalms 26:3', 'Psalms', 26, 3, 'ځکه ستا تلپاتې مینه زما په سترګو کې ده زه تېرومه خپل ژوند ستا وفادارۍ کې', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms26_verse_3.mp3', '', 1761754199, 1761754199),
(53717, 'Psalms 26:4', 'Psalms', 26, 4, 'د دروغجنو خلکو ملګرتیا نه کوم د منافقو هېڅ ملتیا نه کوم', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms26_verse_4.mp3', '', 1761754199, 1761754199),
(53718, 'Psalms 26:5', 'Psalms', 26, 5, 'زه د بدانو د ناستې نه نفرت کومه او د بدکارانو سره نه کښېنمه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms26_verse_5.mp3', '', 1761754199, 1761754199),
(53719, 'Psalms 26:6', 'Psalms', 26, 6, 'خپل لاسونه زه وینځمه چې دا وښایم بې‌ګناه یم قربانګاه نه دې تاوېږم ای څښتنه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms26_verse_6.mp3', '', 1761754199, 1761754199),
(53720, 'Psalms 26:7', 'Psalms', 26, 7, 'په لوړ اواز وایم سندرې او ادا کوم ستا شکر بیانومه زه ستا ټول عجیبه کارونه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms26_verse_7.mp3', '', 1761754199, 1761754199),
(53721, 'Psalms 26:8', 'Psalms', 26, 8, 'ای څښتنه، هغه کور کې چې ته اوسې په ما ګران دی هغه ځای کې چې جلال د ستا اوسیږي په ما ګران دی', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms26_verse_8.mp3', '', 1761754199, 1761754199),
(53722, 'Psalms 26:9', 'Psalms', 26, 9, 'ګناهکارو سره مه تباه کوه ما د قاتلو له تقدیره ته ساته ما', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms26_verse_9.mp3', '', 1761754199, 1761754199),
(53723, 'Psalms 26:10', 'Psalms', 26, 10, 'هغه خلک چې جوړوي پلانونه تل د بدۍ چې همېش دې ته تیار وي رشوت واخلي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms26_verse_10.mp3', '', 1761754199, 1761754199),
(53724, 'Psalms 26:11', 'Psalms', 26, 11, 'خو زه کړم سم کارونه رحم وکړه ته په ما او نجات راکړه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms26_verse_11.mp3', '', 1761754199, 1761754199),
(53725, 'Psalms 26:12', 'Psalms', 26, 12, 'زه د ټولو خطرونو نه خوندي یم په لویه غونډه کې ثنا او صفت به د څښتن کومه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms26_verse_12.mp3', '', 1761754199, 1761754199),
(53726, 'Isaiah 24:1', 'Isaiah', 24, 1, 'ګورئ، نژدې دی چې څښتن ځمکه ورانه او ویجاړه او شاړه کړي. هغه به د ځمکې مخ کندې کپرې او خلک به یې خواره واره کړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah24_verse_1.mp3', '', 1761754199, 1761754199),
(53727, 'Isaiah 24:2', 'Isaiah', 24, 2, 'که هغه عادي خلک وي یا کاهنان، غلامان وي یا باداران، وینځې وي یا بادارانې، اخیستونکي یا خرڅوونکي، پور ورکوونکي یا پور اخیستونکي، د دې ټولو تقدیر او قسمت به یوشان وي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah24_verse_2.mp3', '', 1761754199, 1761754199),
(53728, 'Isaiah 24:3', 'Isaiah', 24, 3, 'ځمکه به په پوره توګه ویجاړه او لوټ شي. دا څښتن ویلي دي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah24_verse_3.mp3', '', 1761754199, 1761754199),
(53729, 'Isaiah 24:4', 'Isaiah', 24, 4, 'ځمکه وچیږي، هرڅه مړاوي کیږي او د نړۍ بنیاد سستیږي. د نړۍ غوره خلک کمزوري کیږي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah24_verse_4.mp3', '', 1761754199, 1761754199),
(53730, 'Isaiah 24:5', 'Isaiah', 24, 5, 'خلکو د ځمکې مخ ناپاکه کړی دی، ځکه چې هغوی د څښتن د حکمونو څخه سرغړونه کړی ده او د هغه تلپاتې لوظ یې مات کړی دی.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah24_verse_5.mp3', '', 1761754199, 1761754199),
(53731, 'Isaiah 24:6', 'Isaiah', 24, 6, 'نو په دې خاطر ځمکه لعنتي شوې ده. خلک یې د خپلو کړنو سزا ویني او ورځ په ورځ د هغوی شمېر کمیږي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah24_verse_6.mp3', '', 1761754199, 1761754199),
(53732, 'Isaiah 24:7', 'Isaiah', 24, 7, 'د انګورو تاکونه وچیږي او شراب کمیږي. کوم خلک چې یو وخت خوشحاله وو اوس اوسیلي وباسي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah24_verse_7.mp3', '', 1761754199, 1761754199),
(53733, 'Isaiah 24:8', 'Isaiah', 24, 8, 'د هغوی له خوشحالۍ ډک د چمبو او ربابونو اواز او د چړچو کوونکو اوازونه نور نه اورېدل کیږي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah24_verse_8.mp3', '', 1761754199, 1761754199),
(53734, 'Isaiah 24:9', 'Isaiah', 24, 9, 'له بده مرغه خلک نور شراب نه څښي او سندرې نه وایي، هغوی ته شراب خوند نه ورکوي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah24_verse_9.mp3', '', 1761754199, 1761754199),
(53735, 'Isaiah 24:10', 'Isaiah', 24, 10, 'ښار وران او ګډوډ شوی دی او د هر یو کور دروازه تړلې ده، ترڅو هېڅوک ورننه نه وځي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah24_verse_10.mp3', '', 1761754199, 1761754199),
(53736, 'Isaiah 24:11', 'Isaiah', 24, 11, 'خلک په کوڅو کې د شرابو د نشتون له امله چیغې وهي. خوښي د تل دپاره له منځه تللې او خوشحالي د ځمکې له مخه ورکه شوې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah24_verse_11.mp3', '', 1761754199, 1761754199),
(53737, 'Isaiah 24:12', 'Isaiah', 24, 12, 'ښار وران شوی او دروازې یې دړې وړې شوې دي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah24_verse_12.mp3', '', 1761754199, 1761754199),
(53738, 'Isaiah 24:13', 'Isaiah', 24, 13, 'نو د نړۍ ټول قومونه به داسې شي لکه د زیتون د هغې ونې په شان چې مېوه یې راټوله او یا د هغه تاک په شان چې انګور یې شکول شوي وي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah24_verse_13.mp3', '', 1761754199, 1761754199),
(53739, 'Isaiah 24:14', 'Isaiah', 24, 14, 'ژوندي پاتې شوي خلک د خوشحالۍ سندرې وایي. هغوی چې په لوېدیځ کې دي څښتن ته په لوړ اواز جلال ورکوي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah24_verse_14.mp3', '', 1761754199, 1761754199),
(53740, 'Isaiah 24:15', 'Isaiah', 24, 15, 'څوک چې په ختیځ کې دي، د څښتن ستاینه وکړئ. څوک چې د بحیرې په غاړو او جزیرو کې دي، د اسراییلو د څښتن خدای ثنا او صفت وکړئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah24_verse_15.mp3', '', 1761754199, 1761754199),
(53741, 'Isaiah 24:16', 'Isaiah', 24, 16, 'مونږ د نړۍ له هرې خوا د عادل خدای د ثنا او صفت سندرې اورو. خو افسوس زما په حال! زه د خاینانو د خیانت د دوام له امله ډنګر او کمزوری شوی یم. د هغوی ټګي نوره هم زیاتیږي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah24_verse_16.mp3', '', 1761754199, 1761754199),
(53742, 'Isaiah 24:17', 'Isaiah', 24, 17, 'ای د نړۍ خلکو واورئ! وېره، کندې او دامونه تاسو ته تیار دي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah24_verse_17.mp3', '', 1761754199, 1761754199),
(53743, 'Isaiah 24:18', 'Isaiah', 24, 18, 'که څوک له وېرې تښتي هغه به په کنده کې لویږي، که څوک له کندې ووځي هغه به په دام کې راګېر شي. سخت بارانونه وریږي او د ځمکې بنیادونه لړزیږي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah24_verse_18.mp3', '', 1761754199, 1761754199),
(53744, 'Isaiah 24:19', 'Isaiah', 24, 19, 'ځمکه به بیخي وچوي، هغه به سره بېله شي او سخته به ولړزیږي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah24_verse_19.mp3', '', 1761754199, 1761754199),
(53745, 'Isaiah 24:20', 'Isaiah', 24, 20, 'ځمکه به لکه د نشه سړي په شان کږه وږه لاړه شي او هغه به د یوې جونګړې په شان وي چې په توفان کې زنګیږي. نړۍ به د خپلو ګناهونو له امله کړوپه شي، هغه به داسې راوغورځیږي چې بیا به هېڅکله راپورته نه شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah24_verse_20.mp3', '', 1761754199, 1761754199),
(53746, 'Isaiah 24:21', 'Isaiah', 24, 21, 'په هغه ورځ به څښتن په اسمان کې اسماني قدرتونو ته او په ځمکه کې د نړۍ پاچاهانو ته سزا ورکړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah24_verse_21.mp3', '', 1761754199, 1761754199),
(53747, 'Isaiah 24:22', 'Isaiah', 24, 22, 'خدای به هغوی د بندیانو په توګه په یوه کنده کې راغونډ کړي او له ډېرو ورځو وروسته به ورته سزا ورکړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah24_verse_22.mp3', '', 1761754199, 1761754199),
(53748, 'Isaiah 24:23', 'Isaiah', 24, 23, 'نو سپوږمۍ به تیاره شي او لمر به نور نه ځلیږي، ځکه چې مطلق قادر څښتن به په اورشلیم کې د صهیون په غره باندې پاچاهي کوي او مشران به د هغه جلال ویني.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah24_verse_23.mp3', '', 1761754199, 1761754199),
(53749, 'Songofsongs 7:1', 'Songofsongs', 7, 1, 'ستا پښې په څپلو کښې څومره ښُکلې ښکارينه، اے د شهزادګۍ لورې. ستا غونډى پتونونه د قيمتى کاڼو په شان دينه، لکه چې دا يو ماهر زرګر جوړ کړى وينه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/songofsongs7_verse_1.mp3', '', 1761754199, 1761754199),
(53750, 'Songofsongs 7:2', 'Songofsongs', 7, 2, 'ستا نوم د يوې پيالۍ په شان دېنه لکه چې د خوشبوداره ميو نه ډکه وينه. ستا پښې لکه د غنمو د ګېډۍ په شان دينه چې ګېرچاپېره ترې نه د لاله ګلونه راتاو شوى وينه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/songofsongs7_verse_2.mp3', '', 1761754199, 1761754199),
(53751, 'Songofsongs 7:3', 'Songofsongs', 7, 3, 'ستا سينې لکه د هوسو د جوړه بچو په شان دينه،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/songofsongs7_verse_3.mp3', '', 1761754199, 1761754199),
(53752, 'Songofsongs 7:4', 'Songofsongs', 7, 4, 'ستا غړۍ لکه د هاتى د غاښونو نه جوړه شوې مينارې په شان ښائسته ده نه. ستا سترګې د حسبون ښار د ځلېدونکو تالابونو په شان دينه، کوم تالابونه چې د دې ښار د بيت‌رابيم دروازې سره دينه. ستا پوزه د لبنان د برج په شان ښائسته ده نه چې د دمشق ښار ترې نه ښکارينه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/songofsongs7_verse_4.mp3', '', 1761754199, 1761754199),
(53753, 'Songofsongs 7:5', 'Songofsongs', 7, 5, 'ستا سر لکه د کرمل د غرۀ په شان اوچت دېنه، ستا د زلفو ښائست لکه د شاهى ګُلکارۍ په شان دېنه تر دې چې بادشاهان هم ستا د کمڅو د ولونو بنديوان دينه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/songofsongs7_verse_5.mp3', '', 1761754199, 1761754199),
(53754, 'Songofsongs 7:6', 'Songofsongs', 7, 6, 'اے محبوبې، تۀ څومره ښُکلې او حسينه ينه، تۀ څومره د خوشحالو نه ډکه ينه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/songofsongs7_verse_6.mp3', '', 1761754199, 1761754199),
(53755, 'Songofsongs 7:7', 'Songofsongs', 7, 7, 'ستا قد او قامت د کجورې د ونې په شان دېنه، او ستا سينې د مېوو د غونچو په شان دينه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/songofsongs7_verse_7.mp3', '', 1761754199, 1761754199),
(53756, 'Songofsongs 7:8', 'Songofsongs', 7, 8, 'ما وئيل زۀ به د کجورې ونې ته وخېژمه او کجورو ته به يې لاس وروړمه. ستا سينې دې د مېوو د غونچو په شان وينه، او ستا د خولې خوشبو دې لکه د سيوانو په شان وينه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/songofsongs7_verse_8.mp3', '', 1761754199, 1761754199),
(53757, 'Songofsongs 7:9', 'Songofsongs', 7, 9, 'او ستا شونډې د اعلىٰ ميو په شان دينه. نو دا مے دې زما د جانان په غاښونو او شونډو باندې په نرمۍ سره وبهيږينه. محبوبه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/songofsongs7_verse_9.mp3', '', 1761754199, 1761754199),
(53758, 'Songofsongs 7:10', 'Songofsongs', 7, 10, 'زۀ د خپل جانان يمه، او د هغۀ زړۀ ما غواړينه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/songofsongs7_verse_10.mp3', '', 1761754199, 1761754199),
(53759, 'Songofsongs 7:11', 'Songofsongs', 7, 11, 'زما جانانه راشه، راځه چې بهر پټو ته لاړ شُو نه او هلته په کلى کښې شپه تېره کړو نه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/songofsongs7_verse_11.mp3', '', 1761754199, 1761754199),
(53760, 'Songofsongs 7:12', 'Songofsongs', 7, 12, 'راځه چې سحر وختى پاڅيږونه او د انګورو باغونو ته لاړ شونه چې د انګورو د ځيلو راټوکېدل ووينو او چې انارو ګلونه کړى دى کۀ نه، هلته به زۀ خپله مينه تا ته وښايمه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/songofsongs7_verse_12.mp3', '', 1761754199, 1761754199),
(53761, 'Songofsongs 7:13', 'Songofsongs', 7, 13, 'هلته به د مړه غونو بوټو خپله خوشبو راپرېښې وينه، او د ټولو نه ښې مېوې به زمونږ دروازې سره وينه، نوې او زاړۀ خوندونه، جانانه کوم چې ما ستا دپاره ساتلى دينه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/songofsongs7_verse_13.mp3', '', 1761754199, 1761754199),
(53762, 'Job 41:1', 'Job', 41, 1, 'سمندرى بلاګانې تۀ د کُنډې سره راويستلے شې، يا د دې ژبه د پړى سره تړلے شې څۀ؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job41_verse_1.mp3', '', 1761754199, 1761754199),
(53763, 'Job 41:2', 'Job', 41, 2, 'ولې تۀ دې ته پېزوان اچولے شې، يا يې په ژامنه کښې کُنډه اچولے شې؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job41_verse_2.mp3', '', 1761754199, 1761754199),
(53764, 'Job 41:3', 'Job', 41, 3, 'ولې دا به د رحم دپاره تا ته ډېر مِنتُونه وکړى؟ يا به نرمې خبرې درته وکړى؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job41_verse_3.mp3', '', 1761754199, 1761754199),
(53765, 'Job 41:4', 'Job', 41, 4, 'دا به تا سره يو لوظ وکړى څۀ چې ټول عُمر به ستا غلام وى؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job41_verse_4.mp3', '', 1761754199, 1761754199),
(53766, 'Job 41:5', 'Job', 41, 5, 'ولې تۀ به دا د يو مارغۀ په شان وساتې څۀ، يا تۀ به دا وتړې څۀ دپاره د دې چې ستا وينځې ورسره لوبې وکړى؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job41_verse_5.mp3', '', 1761754199, 1761754199),
(53767, 'Job 41:6', 'Job', 41, 6, 'ولې سوداګر به د دې سودا وکړى؟ چې په بازار کښې يې خرڅ کړى؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job41_verse_6.mp3', '', 1761754199, 1761754199),
(53768, 'Job 41:7', 'Job', 41, 7, 'ولې د هغې په څرمن باندې غشى څۀ اثر کوى، او د دې سر د نېزو سره غوڅولے شې؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job41_verse_7.mp3', '', 1761754199, 1761754199),
(53769, 'Job 41:8', 'Job', 41, 8, 'کۀ تۀ خپل لاس د دې سره ولګوې، نو د جنګ په مزه به پوهه شې، او بيا به هيڅکله داسې نۀ کوې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job41_verse_8.mp3', '', 1761754199, 1761754199),
(53770, 'Job 41:9', 'Job', 41, 9, 'نه، د دې نيول څۀ فائده نۀ کوى، او کوم ښکارى چې د دې د نيولو کوشش کوى نو هغه به راوغورزولے شى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job41_verse_9.mp3', '', 1761754199, 1761754199),
(53771, 'Job 41:10', 'Job', 41, 10, 'هيڅ څوک هم دا جرأت نۀ شى کولے چې کار ورسره وساتى. او د دې په وړاندې څوک ټېنګېدے شى؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job41_verse_10.mp3', '', 1761754199, 1761754199),
(53772, 'Job 41:11', 'Job', 41, 11, 'چا ما له څۀ راکړى دى چې زۀ بدله ورکړم؟ د آسمان نه لاندې هر څۀ زما دى؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job41_verse_11.mp3', '', 1761754199, 1761754199),
(53773, 'Job 41:12', 'Job', 41, 12, 'زۀ به د دې د بدن د اندامونو په حقله خاموشى نۀ اختياروم، يا د دې د لوئ طاقت او د دې د ښۀ بدن په حقله به وايم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job41_verse_12.mp3', '', 1761754199, 1761754199),
(53774, 'Job 41:13', 'Job', 41, 13, 'د دې نه څرمن څوک ويستے شى؟ د دې ډکه څرمن څوک سورے کولے شى؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job41_verse_13.mp3', '', 1761754199, 1761754199),
(53775, 'Job 41:14', 'Job', 41, 14, 'د دې د خولې ژامنې څوک کولاولے شى؟ ځکه چې د دې غاښونه خلق يروى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job41_verse_14.mp3', '', 1761754199, 1761754199),
(53776, 'Job 41:15', 'Job', 41, 15, 'د دې ملا د ډالونو قطارونو نه جوړه ده، دا د يو بل سره کلک انښلى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job41_verse_15.mp3', '', 1761754199, 1761754199),
(53777, 'Job 41:16', 'Job', 41, 16, 'د يو بل سره دومره نزدې دى، چې د دې په مينځ کښې هوا هم نۀ شى تېرېدلے.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job41_verse_16.mp3', '', 1761754199, 1761754199),
(53778, 'Job 41:17', 'Job', 41, 17, 'دا د يو بل سره تړلى شوى دى، دې يو بل نيولے دے او د يو بل نه نۀ جدا کيږى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job41_verse_17.mp3', '', 1761754199, 1761754199),
(53779, 'Job 41:18', 'Job', 41, 18, 'د دې انټوشى لکه د رڼا پړق وى، او د دې سترګې د سحر د سوروالى په شان دى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job41_verse_18.mp3', '', 1761754199, 1761754199),
(53780, 'Job 41:19', 'Job', 41, 19, 'د دې خولې نه د ډيوو شُغلې ځى، او د اور ذرې ترې نه راوځى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job41_verse_19.mp3', '', 1761754199, 1761754199),
(53781, 'Job 41:20', 'Job', 41, 20, 'د دې د پوزې نه لوګے راوځى، لکه چې د پتيلې لاندې د بلو لوخو لوګے وى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job41_verse_20.mp3', '', 1761754199, 1761754199),
(53782, 'Job 41:21', 'Job', 41, 21, 'د دې ساه سکارۀ بلوى، او د دې خولې نه يوه لمبه راوځى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job41_verse_21.mp3', '', 1761754199, 1761754199),
(53783, 'Job 41:22', 'Job', 41, 22, 'د دې څټ مضبوط دے، او چې چرته هم ځى نو هلته يره راځى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job41_verse_22.mp3', '', 1761754199, 1761754199),
