(53785, 'Job 41:24', 'Job', 41, 24, 'د دې زړۀ د کاڼى په شان سخت دے، لکه د ژرندې د کاڼى په شان سخت دے.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job41_verse_24.mp3', '', 1761754199, 1761754199),
