(53788, 'Job 41:27', 'Job', 41, 27, 'دا اوسپنه د بوسو په شان ګڼى، او زېړ د ورَستو شوو لرګو په شان ګڼى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job41_verse_27.mp3', '', 1761754199, 1761754199),
(53789, 'Job 41:28', 'Job', 41, 28, 'غشى دا نۀ شى شړلے، او د ليندې کاڼى خو ورته ګپ ښکارى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job41_verse_28.mp3', '', 1761754199, 1761754199),
(53790, 'Job 41:29', 'Job', 41, 29, 'لَوړ د بوسو په شان ګڼى، او د نرو نېزو په راويستلو پورې دا خندا کوى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job41_verse_29.mp3', '', 1761754199, 1761754199),
(53791, 'Job 41:30', 'Job', 41, 30, 'د دې خېټه د تېرو ماتو شوو شيشو په شان ده، دا په خټه باندې داسې نښه پرېږدى لکه چې په مېخونو سورے شوے وى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job41_verse_30.mp3', '', 1761754199, 1761754199),
(53792, 'Job 41:31', 'Job', 41, 31, 'دا سمندر د يشېدلو اوبو په شان خوځوى، او دا سمندر داسې شاربى لکه شُملې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job41_verse_31.mp3', '', 1761754199, 1761754199),
