(53795, 'Job 41:34', 'Job', 41, 34, 'دا په ټولو کښې ډېر مغرور دے، دا د ټولو ځناورو بادشاه دے.“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job41_verse_34.mp3', '', 1761754199, 1761754199),
(53796, 'Jonah 3:1', 'Jonah', 3, 1, 'بیا په دوهم ځل څښتن یونس ته وویل:', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jonah3_verse_1.mp3', '', 1761754199, 1761754199),
(53797, 'Jonah 3:2', 'Jonah', 3, 2, '«همدا اوس د نینوا لوی ښار ته لاړ شه او هغه پیغام خلکو ته اعلان کړه چې زه یې تاته درکوم.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jonah3_verse_2.mp3', '', 1761754199, 1761754199),
(53798, 'Jonah 3:3', 'Jonah', 3, 3, 'نو یونس د څښتن خبره ومنله او نینوا ته لاړ. نینوا یو ډېر لوی ښار ؤ چې په ګرځېدلو کې یې درې ورځې لګېدلې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jonah3_verse_3.mp3', '', 1761754199, 1761754199),
(53799, 'Jonah 3:4', 'Jonah', 3, 4, 'یونس د ښار په منځ کې روان شو او د یوې ورځې له ګرځېدلو څخه وروسته هغه خلکو ته داسې اعلان وکړ:«نینوا به په څلوېښتو ورځو کې وران شي!»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jonah3_verse_4.mp3', '', 1761754199, 1761754199),
(53800, 'Jonah 3:5', 'Jonah', 3, 5, 'د نینوا خلکو د خدای په پیغام باندې باور وکړ. نو هغوی دا اعلان وکړ چې هر یو تن باید روژه ونیسي او ټول خلک د لوی څخه نیولې تر کوچني پورې باید د ویر کالي واغوندي، ترڅو دا وښایي چې توبه یې ویستلې ده.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jonah3_verse_5.mp3', '', 1761754199, 1761754199),
(53801, 'Jonah 3:6', 'Jonah', 3, 6, 'کله چې د نینوا پاچا د دې خبرې په هکله واورېدل، هغه د خپل تخت څخه پاڅېد، خپله چپنه یې وویستله، د ویر کالي یې واغوستل او په ایرو باندې کښېناست.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jonah3_verse_6.mp3', '', 1761754199, 1761754199),
(53802, 'Jonah 3:7', 'Jonah', 3, 7, 'هغه د نینوا خلکو ته داسې یو اعلان وکړ: «د پاچا او د هغه د درباریانو له خوا یو حکم وشو چې هېڅوک دې څه نه خوري. ټول خلک او حیوانات، پادې او پسونه د خوراک او د څښاک څخه منع دي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jonah3_verse_7.mp3', '', 1761754199, 1761754199),
(53803, 'Jonah 3:8', 'Jonah', 3, 8, 'ټول خلک او حیوانات باید د ویر کالي واغوندي. هر یو باید په جدي توګه خدای ته دعا وکړي او د خپلو بدو کارونو او زور زیاتي څخه لاس واخلي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jonah3_verse_8.mp3', '', 1761754199, 1761754199),
(53804, 'Jonah 3:9', 'Jonah', 3, 9, 'څوک پوهیږي؟ کېدای شي بیاهم خدای خپله پرېکړه بدله کړي او د خپل سخت قهر څخه راوګرځي، ترڅو مونږ هلاک نه شو.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jonah3_verse_9.mp3', '', 1761754199, 1761754199),
(53805, 'Jonah 3:10', 'Jonah', 3, 10, 'کله چې خدای ولیدل چې هغوی څه وکړل او څنګه هغوی د بدو لارو څخه راوګرځېدل، نو هغه خپله پرېکړه بدله کړه او هغه تباهي یې ورباندې نازله نه کړه چې د هغې ګواښ یې کړی ؤ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jonah3_verse_10.mp3', '', 1761754199, 1761754199),
(53806, 'Ezekiel 9:1', 'Ezekiel', 9, 1, 'بیا ما واورېدل چې څښتن په لوړ اواز وویل: «ای هغو کسانو چې ښار ته د سزا ورکولو دپاره ټاکل شوي یئ، دلته راشئ او خپلې وژونکې وسلې د ځان سره راوړئ.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel9_verse_1.mp3', '', 1761754199, 1761754199),
(53807, 'Ezekiel 9:2', 'Ezekiel', 9, 2, 'ناڅاپه شپږ تنه د شمالي دروازې نه راښکاره شول، د هر یو په لاس کې وژونکې وسله وه. د هغوی سره یو سړی هم ؤ چې د کتان کالي یې اغوستي وو او د لیکلو سامان یې په ملا پورې تړلی ؤ. هغوی ټول د څښتن کور ته ننوتل او د قربانۍ د برنجي ځای په څنګ کې ودرېدل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel9_verse_2.mp3', '', 1761754199, 1761754199),
(53808, 'Ezekiel 9:3', 'Ezekiel', 9, 3, 'نو د اسراییلو د خدای جلال د هغو اسماني مخلوقاتو څخه چې هلته موجود وو، راپورته شو او د څښتن د کور د دروازې خولې ته روان شو. څښتن هغه سړي ته چې د کتان کالي یې اغوستي وو او د لیکلو سامان یې په ملا پورې تړلی ؤ،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel9_verse_3.mp3', '', 1761754199, 1761754199),
(53809, 'Ezekiel 9:4', 'Ezekiel', 9, 4, 'نارې کړې: «د اورشلیم په ټول ښار کې وګرځه او د هغو کسانو په تندي باندې چې په ښار کې د کرکې وړ کارونو په خاطر ویر او ماتم کوي، یوه نښه ولګوه.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel9_verse_4.mp3', '', 1761754199, 1761754199),
